import AppKit
import SwiftUI
import UsageCore

/// Each provider's logo as T3 Code draws it in its provider picker (Devin's from the Devin app), in its dark-appearance colors (the
/// panel is always dark). Path data comes from T3 Code's bundled provider definitions.
enum ProviderLogo {
    private static let cache: [Provider: NSImage] = Dictionary(uniqueKeysWithValues: Provider.allCases.compactMap { provider in
        image(for: provider).map { (provider, $0) }
    })

    static func nsImage(_ provider: Provider) -> NSImage? {
        cache[provider]
    }

    /// The logo for drawing as a template, in one color whose strength comes from alpha. Two-tone
    /// logos give their darker part partial alpha, so it doesn't merge into the rest as solid color.
    static func template(_ provider: Provider) -> NSImage? {
        templateCache[provider] ?? cache[provider]
    }

    private static let templateCache: [Provider: NSImage] = templateSVG.compactMapValues { NSImage(data: Data($0.utf8)) }

    private static let templateSVG: [Provider: String] = [
        // OpenCode's mark is a light frame around a dark block; filled solid, it reads as a slab.
        .opencode: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 32 40\"><path d=\"M24 32H8V16H24V32Z\" fill=\"#000\" fill-opacity=\"0.4\"/><path d=\"M24 8H8V32H24V8ZM32 40H0V0H32V40Z\" fill=\"#000\"/></svg>",
    ]

    private static func image(for provider: Provider) -> NSImage? {
        switch provider {
        case .antigravity:
            Data(base64Encoded: antigravityPNG).flatMap(NSImage.init(data:))
        default:
            svg[provider].flatMap { NSImage(data: Data($0.utf8)) }
        }
    }

