/// A provider's logo at a given size. "All" is drawn as a stack of squares.
struct ProviderIcon: View {
    let provider: Provider?
    var size: CGFloat = 16

    var body: some View {
        if let provider, let image = ProviderLogo.nsImage(provider) {
            Image(nsImage: image)
                .resizable()
                .interpolation(.high)
                .aspectRatio(contentMode: .fit)
                .frame(width: size, height: size)
                // Drawn as is, so glass doesn't lighten the brand colors with vibrancy.
                .drawingGroup()
        } else {
            Image(systemName: "square.grid.2x2.fill")
                .font(.system(size: size * 0.82, weight: .semibold))
                .frame(width: size, height: size)
        }
    }
}
